-- Generated by airbnb_etl.ddl. Do not edit by hand.
-- Refresh with: python -m airbnb_etl.ddl
--
-- Inside Airbnb city snapshot. listings is the analytical projection of the
-- detailed gzip extract (descriptions, photo URLs, and host essays stay out).
-- calendars is the high-volume table and stays narrow: stay date, availability,
-- and night bounds. reviews holds comment text. review_dates is the summary
-- file, a date spine with no comment body.
-- Fact tables have no foreign keys. A multi-gigabyte COPY should not pay for
-- a referential check on every calendar or review row.

CREATE TABLE IF NOT EXISTS markets (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  name VARCHAR(256) NOT NULL,
  country VARCHAR(64) NOT NULL,
  region VARCHAR(64) NOT NULL,
  city VARCHAR(64) NOT NULL,
  loaded_at TIMESTAMPTZ NULL,
  CONSTRAINT pk_markets PRIMARY KEY (market_code, snapshot_date)
);

CREATE TABLE IF NOT EXISTS pipeline_runs (
  run_id VARCHAR(36) NOT NULL,
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  status VARCHAR(32) NOT NULL,
  dry_run BOOLEAN NOT NULL,
  started_at TIMESTAMPTZ NULL,
  finished_at TIMESTAMPTZ NULL,
  error_message TEXT NULL,
  stats JSONB NULL,
  CONSTRAINT pk_pipeline_runs PRIMARY KEY (run_id)
);

CREATE TABLE IF NOT EXISTS dataset_files (
  run_id VARCHAR(36) NOT NULL,
  dataset_name VARCHAR(64) NOT NULL,
  source_url TEXT NOT NULL,
  storage_key TEXT NOT NULL,
  byte_size BIGINT NOT NULL,
  sha256 CHAR(64) NOT NULL,
  row_count BIGINT NOT NULL,
  rejected_count INTEGER NOT NULL,
  elapsed_ms INTEGER NOT NULL,
  reused BOOLEAN NOT NULL,
  CONSTRAINT pk_dataset_files PRIMARY KEY (run_id, dataset_name),
  CONSTRAINT fk_dataset_files_run FOREIGN KEY (run_id) REFERENCES pipeline_runs(run_id)
);

CREATE TABLE IF NOT EXISTS listings (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  listing_id BIGINT NOT NULL,
  name VARCHAR(512) NULL,
  host_id BIGINT NULL,
  host_name VARCHAR(256) NULL,
  host_since DATE NULL,
  host_is_superhost BOOLEAN NULL,
  host_listings_count INTEGER NULL,
  host_identity_verified BOOLEAN NULL,
  host_response_rate NUMERIC(6,2) NULL,
  host_acceptance_rate NUMERIC(6,2) NULL,
  neighbourhood VARCHAR(256) NULL,
  neighbourhood_cleansed VARCHAR(256) NULL,
  neighbourhood_group VARCHAR(256) NULL,
  latitude NUMERIC(9,6) NULL,
  longitude NUMERIC(9,6) NULL,
  property_type VARCHAR(128) NULL,
  room_type VARCHAR(128) NULL,
  accommodates INTEGER NULL,
  bathrooms NUMERIC(4,1) NULL,
  bedrooms INTEGER NULL,
  beds INTEGER NULL,
  amenities TEXT NULL,
  price NUMERIC(14,2) NULL,
  price_quote_total NUMERIC(14,2) NULL,
  price_quote_per_night NUMERIC(14,2) NULL,
  minimum_nights INTEGER NULL,
  maximum_nights INTEGER NULL,
  has_availability BOOLEAN NULL,
  availability_30 INTEGER NULL,
  availability_365 INTEGER NULL,
  number_of_reviews INTEGER NULL,
  number_of_reviews_ltm INTEGER NULL,
  number_of_reviews_l30d INTEGER NULL,
  first_review DATE NULL,
  last_review DATE NULL,
  review_scores_rating NUMERIC(5,2) NULL,
  review_scores_accuracy NUMERIC(5,2) NULL,
  review_scores_cleanliness NUMERIC(5,2) NULL,
  review_scores_checkin NUMERIC(5,2) NULL,
  review_scores_communication NUMERIC(5,2) NULL,
  review_scores_location NUMERIC(5,2) NULL,
  review_scores_value NUMERIC(5,2) NULL,
  estimated_occupancy_l365d NUMERIC(10,2) NULL,
  estimated_revenue_l365d NUMERIC(14,2) NULL,
  instant_bookable BOOLEAN NULL,
  reviews_per_month NUMERIC(6,2) NULL,
  license VARCHAR(256) NULL,
  CONSTRAINT pk_listings PRIMARY KEY (market_code, snapshot_date, listing_id)
);

CREATE TABLE IF NOT EXISTS listing_summaries (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  listing_id BIGINT NOT NULL,
  name VARCHAR(512) NULL,
  host_id BIGINT NULL,
  host_profile_id VARCHAR(256) NULL,
  host_name VARCHAR(256) NULL,
  neighbourhood_group VARCHAR(256) NULL,
  neighbourhood VARCHAR(256) NULL,
  latitude NUMERIC(9,6) NULL,
  longitude NUMERIC(9,6) NULL,
  room_type VARCHAR(128) NULL,
  price NUMERIC(14,2) NULL,
  minimum_nights INTEGER NULL,
  number_of_reviews INTEGER NULL,
  last_review DATE NULL,
  reviews_per_month NUMERIC(6,2) NULL,
  calculated_host_listings_count INTEGER NULL,
  availability_365 INTEGER NULL,
  number_of_reviews_ltm INTEGER NULL,
  license VARCHAR(256) NULL,
  CONSTRAINT pk_listing_summaries PRIMARY KEY (market_code, snapshot_date, listing_id)
);

CREATE TABLE IF NOT EXISTS calendars (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  listing_id BIGINT NOT NULL,
  stay_date DATE NOT NULL,
  available BOOLEAN NULL,
  minimum_nights INTEGER NULL,
  maximum_nights INTEGER NULL,
  CONSTRAINT pk_calendars PRIMARY KEY (market_code, snapshot_date, listing_id, stay_date)
);

CREATE TABLE IF NOT EXISTS reviews (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  review_id BIGINT NOT NULL,
  listing_id BIGINT NOT NULL,
  review_date DATE NULL,
  reviewer_id BIGINT NULL,
  reviewer_name VARCHAR(256) NULL,
  comments TEXT NULL,
  CONSTRAINT pk_reviews PRIMARY KEY (market_code, snapshot_date, review_id)
);

CREATE TABLE IF NOT EXISTS review_dates (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  source_row INTEGER NOT NULL,
  listing_id BIGINT NOT NULL,
  review_date DATE NOT NULL,
  CONSTRAINT pk_review_dates PRIMARY KEY (market_code, snapshot_date, source_row)
);

CREATE TABLE IF NOT EXISTS neighbourhoods (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  neighbourhood VARCHAR(256) NOT NULL,
  neighbourhood_group VARCHAR(256) NULL,
  CONSTRAINT pk_neighbourhoods PRIMARY KEY (market_code, snapshot_date, neighbourhood)
);

CREATE TABLE IF NOT EXISTS neighbourhood_geometries (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  neighbourhood VARCHAR(256) NOT NULL,
  neighbourhood_group VARCHAR(256) NULL,
  geometry JSONB NULL,
  CONSTRAINT pk_neighbourhood_geometries PRIMARY KEY (market_code, snapshot_date, neighbourhood)
);

CREATE TABLE IF NOT EXISTS neighbourhood_metrics (
  market_code VARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  neighbourhood VARCHAR(256) NOT NULL,
  listings INTEGER NOT NULL,
  median_price NUMERIC(14,2) NULL,
  avg_price NUMERIC(14,2) NULL,
  avg_rating NUMERIC(5,2) NULL,
  superhost_share NUMERIC(7,4) NULL,
  avg_availability_365 NUMERIC(8,2) NULL,
  estimated_revenue NUMERIC(16,2) NULL,
  avg_occupancy NUMERIC(10,2) NULL,
  CONSTRAINT pk_neighbourhood_metrics PRIMARY KEY (market_code, snapshot_date, neighbourhood)
);

CREATE INDEX IF NOT EXISTS ix_listings_room ON listings (market_code, snapshot_date, room_type);

CREATE INDEX IF NOT EXISTS ix_listings_price ON listings (market_code, snapshot_date, price);

CREATE INDEX IF NOT EXISTS ix_listings_neighbourhood ON listings (market_code, snapshot_date, neighbourhood_cleansed);

CREATE INDEX IF NOT EXISTS ix_reviews_listing ON reviews (market_code, snapshot_date, listing_id, review_date);

CREATE INDEX IF NOT EXISTS ix_review_dates_listing ON review_dates (market_code, snapshot_date, listing_id, review_date);

CREATE OR REPLACE VIEW market_metrics AS
SELECT
  market_code,
  snapshot_date,
  COUNT(*) AS listings,
  AVG(price) AS avg_price,
  AVG(review_scores_rating) AS avg_rating,
  AVG(CASE WHEN host_is_superhost IS TRUE THEN 1.0 WHEN host_is_superhost IS FALSE THEN 0.0 END) AS superhost_share,
  SUM(estimated_revenue_l365d) AS estimated_revenue,
  AVG(estimated_occupancy_l365d) AS avg_occupancy,
  AVG(availability_365) AS avg_availability_365
FROM listings
GROUP BY market_code, snapshot_date;
